<?php require_once __DIR__.'/config/security.php'; require_permission('monitoring.view'); $page_title='Advanced Analytics'; $rows=$pdo->query("SELECT DATE_FORMAT(recorded_at,'%Y-%m-%d %H:00:00') bucket, ROUND(AVG(download_mbps),2) down, ROUND(AVG(upload_mbps),2) up FROM network_metrics GROUP BY bucket ORDER BY bucket DESC LIMIT 24")->fetchAll(); $status=$pdo->query("SELECT status,COUNT(*) total FROM device_status_history WHERE changed_at>=NOW()-INTERVAL 30 DAY GROUP BY status")->fetchAll(); include __DIR__.'/partials/header.php'; ?>
<div class="hero compact"><div><div class="eyebrow">HISTORICAL ANALYTICS</div><h1>Traffic, uptime & downtime</h1><p>Historical records become meaningful after monitoring jobs populate <code>network_metrics</code> and <code>device_status_history</code>.</p></div></div>
<div class="panel"><div class="panel-head"><div><h3>Last 24 recorded hourly samples</h3><p>Average download and upload throughput.</p></div></div><div class="chart-box"><canvas id="trafficChart" height="120"></canvas></div></div>
<div class="stats-grid"><?php foreach($status as $x):?><div class="stat-card"><small><?=e($x['status'])?> EVENTS · 30D</small><strong><?=e((string)$x['total'])?></strong><span>Status changes recorded</span></div><?php endforeach;?></div>
<div class="panel"><div class="panel-head"><div><h3>Uptime / downtime reporting</h3><p>For accurate uptime, schedule authorized monitoring to record every poll/status transition.</p></div></div><div class="backup-note">This report intentionally does not invent uptime percentages. Until real or scheduled monitoring data exists, the dashboard will show the amount of collected status history rather than a misleading uptime score.</div></div>
<script>const data=<?=json_encode(array_reverse($rows))?>;const c=document.getElementById('trafficChart'),ctx=c.getContext('2d');let w=c.width=c.clientWidth*2,h=c.height=c.clientHeight*2;ctx.scale(2,2);w/=2;h/=2;ctx.font='10px sans-serif';if(!data.length){ctx.fillText('No monitoring history yet.',20,40)}else{let max=Math.max(...data.map(x=>Math.max(+x.down,+x.up)),1),step=w/(data.length-1||1);ctx.beginPath();data.forEach((x,i)=>{let y=h-20-(+x.down/max)*(h-45);i?ctx.lineTo(i*step,y):ctx.moveTo(i*step,y)});ctx.stroke();ctx.beginPath();data.forEach((x,i)=>{let y=h-20-(+x.up/max)*(h-45);i?ctx.lineTo(i*step,y):ctx.moveTo(i*step,y)});ctx.stroke();ctx.fillText('Download',10,15);ctx.fillText('Upload',90,15)}</script>
<?php include __DIR__.'/partials/footer.php'; ?>
